const BRANCH_WORKFLOW_ACTIONS = new Set<BranchWorkflowAction>([
  'commit',
  'pull',
  'push',
  'create-branch',
  'create-pull-request',
]);

type BranchDashboardPreferences = {
  branchView: 'all' | 'mine' | 'needs-my-review' | 'ready' | 'ci-failing' | 'cleanup';
  branchSort: 'activity' | 'readiness' | 'drift' | 'name';
  branchSortDirection: 'asc' | 'desc';
  branchGroup: 'none' | 'readiness' | 'pull-request' | 'branch-family';
  branchScmChips: boolean;
};

const BRANCH_DASHBOARD_PREFERENCE_KEYS = new Set<keyof BranchDashboardPreferences>([
  'branchView',
  'branchSort',
  'branchSortDirection',
  'branchGroup',
  'branchScmChips',
]);

/** Validate the complete, presentation-only branch preference record at the host boundary. */
export function normalizeBranchDashboardPreferences(value: unknown): BranchDashboardPreferences | undefined {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return undefined;
  }
  const candidate = value as Record<string, unknown>;
  if (Object.keys(candidate).some(key => !BRANCH_DASHBOARD_PREFERENCE_KEYS.has(key as keyof BranchDashboardPreferences))) {
    return undefined;
  }
  if (
    !['all', 'mine', 'needs-my-review', 'ready', 'ci-failing', 'cleanup'].includes(String(candidate['branchView']))
    || !['activity', 'readiness', 'drift', 'name'].includes(String(candidate['branchSort']))
    || !['asc', 'desc'].includes(String(candidate['branchSortDirection']))
    || !['none', 'readiness', 'pull-request', 'branch-family'].includes(String(candidate['branchGroup']))
    || typeof candidate['branchScmChips'] !== 'boolean'
  ) {
    return undefined;
  }
  return candidate as BranchDashboardPreferences;
}

/**
 * The repair task's retained, display-safe terminal state. This is deliberately
 * separate from the current testing snapshot: a snapshot says what evidence is
 * on disk, while this says what the routed task actually reported doing.
 */
interface TestingFixResult {
  outcome: TestingFixOutcome;
  summary: string;
  output: string;
  completedAt: string;
  agentId?: string;
}

type LocalCiSetupHelpId =
  | 'docker-windows'
  | 'docker-macos'
  | 'docker-linux'
  | 'github-cli'
  /* Each executor that lives outside AtlasMind, keyed by its own route id. */
  | 'act'
  | 'buildkite'
  | 'woodpecker';

/**
 * Every page this panel can send somebody to, and the only ones.
 *
 * The webview names an id; this table decides the destination. A route's own
 * entry is read from `CI_ROUTES` rather than copied, so the executor row and
 * the link it draws can never disagree about where "Buildkite" goes — and a
 * route whose `docsUrl` is removed loses the link rather than acquiring a
 * stale one.
 */
const LOCAL_CI_SETUP_HELP_URLS: Readonly<Record<LocalCiSetupHelpId, string>> = {
  'docker-windows': 'https://docs.docker.com/desktop/setup/install/windows-install/',
  'docker-macos': 'https://docs.docker.com/desktop/setup/install/mac-install/',
  'docker-linux': 'https://docs.docker.com/engine/install/',
  'github-cli': 'https://cli.github.com/',
  act: findCiRoute('act')?.docsUrl ?? 'https://nektosact.com/',
  buildkite: findCiRoute('buildkite')?.docsUrl ?? 'https://buildkite.com/docs/pipelines',
  woodpecker: findCiRoute('woodpecker')?.docsUrl ?? 'https://woodpecker-ci.org/docs/intro',
};

const LOCAL_CI_TERMINAL_NAME = 'AtlasMind CI';

