interface DashboardLocalCiRunnerSnapshot extends LocalCiRunnerSnapshot {
  /** The effective VS Code value, not a browser-owned toggle. */
  enablement: DashboardLocalCiEnablementSnapshot;
  /**
   * Set when the machine readings on this snapshot came from a remembered
   * inspection rather than one run in this session.
   *
   * Carried as its own field rather than folded into the readings, because the
   * page must be able to say *when* they were taken. A restored reading shown
   * as though it were live is a claim about right now that nobody checked —
   * which is the failure this whole mechanism exists to avoid while still not
   * asking somebody to re-run a probe they ran yesterday.
   */
  rememberedInspection?: {
    observedAt: string;
    ageDays: number;
    /** The shared sentence from `describeRememberedInspection`. */
    detail: string;
  };
}

function readLocalCiRunnerConfiguration(): LocalCiRunnerConfiguration {
  const configuration = vscode.workspace.getConfiguration('atlasmind');
  const shutdown = configuration.get<string>('ci.localRunner.shutdownPolicy', 'ifStartedByAtlasMind');
  const shutdownPolicy: LocalCiShutdownPolicy = shutdown === 'never' || shutdown === 'always'
    ? shutdown
    : 'ifStartedByAtlasMind';
  return {
    enabled: configuration.get<boolean>('ci.localRunner.enabled', false),
    workflowFile: configuration.get<string>('ci.localRunner.workflowFile', 'trusted-local-ci.yml').trim(),
    trustedBranch: configuration.get<string>('ci.localRunner.trustedBranch', 'develop').trim(),
    runnerLabel: configuration.get<string>('ci.localRunner.runnerLabel', 'atlasmind-trusted-linux-{arch}').trim(),
    image: configuration.get<string>('ci.localRunner.image', DEFAULT_LOCAL_CI_IMAGE).trim(),
    shutdownPolicy,
    maxCpus: configuration.get<number>('ci.localRunner.maxCpus', 8),
    maxMemoryGb: configuration.get<number>('ci.localRunner.maxMemoryGb', 16),
    // Clamped inside the planner, so a hand-edited settings file cannot state
    // a share the policy would refuse.
    resourceSharePercent: configuration.get<number>('testing.resourceShare', 50),
  };
}

function readLocalCiRunnerEnablement(): DashboardLocalCiEnablementSnapshot {
  const configuration = vscode.workspace.getConfiguration('atlasmind');
  const inspection = configuration.inspect<boolean>('ci.localRunner.enabled');
  const effective = configuration.get<boolean>('ci.localRunner.enabled', false);
  if (inspection?.workspaceFolderValue !== undefined) {
    return { effective, source: 'workspace-folder', sourceLabel: 'workspace-folder setting' };
  }
  if (inspection?.workspaceValue !== undefined) {
    return { effective, source: 'workspace', sourceLabel: 'workspace setting' };
  }
  if (inspection?.globalValue !== undefined) {
    return { effective, source: 'user-machine', sourceLabel: 'current VS Code user/machine setting' };
  }
  return { effective, source: 'default', sourceLabel: 'default for this VS Code profile and extension host' };
}

const UNREADABLE_CI_WORKFLOW_CAUTION = 'Workflow metadata could not be read safely.';

type ArtifactType = 'persistent' | 'ephemeral';
type ArtifactOrigin = 'manual' | 'generated' | 'tooling';
type ArtifactLifecycle = 'source' | 'build' | 'test' | 'deploy' | 'runtime';
type ArtifactRetention = 'keep' | 'cache' | 'discard';

interface ArtifactSignal {
  /** Opaque, stable address for this row. The webview names it and nothing else. */
  id: string;
  label: string;
  description: string;
  /** Workspace-relative path to open when the artifact exists, or the primary path as a reference. */
  path: string;
  type: ArtifactType;
  origin: ArtifactOrigin;
  lifecycle: ArtifactLifecycle;
  retention: ArtifactRetention;
  exists: boolean;
  /** True when the artifact is persistent+keep but absent — blocks production readiness. */
  needsAttention: boolean;
  /**
   * Which of the three hand-offs this row offers, decided by
   * `classifyArtifactCompliance` on the host.
   *
   * Shipped rather than re-derived in the browser: a second classifier there
   * would eventually disagree with this one, and the symptom would be a control
   * whose icon promises a fix while the draft it opens asks a question.
   */
  complianceIntent: ArtifactComplianceIntent;
  /** The imperative shown on that control, from the same declared rule. */
  complianceAction: string;
}

interface ArtifactSpec {
  label: string;
  description: string;
  /** One or more workspace-relative paths to probe; first match wins. */
  paths: string[];
  type: ArtifactType;
  origin: ArtifactOrigin;
  lifecycle: ArtifactLifecycle;
  retention: ArtifactRetention;
}

